// paragraph-chunker for n8n Code node
// Runs once for all input items ($input.all())

const maxChars = 1000; // change this to suit your desired chunk size

const items = $input.all(); // all incoming items from previous node
const out = [];

function splitIntoParagraphs(text) {
  if (!text || typeof text !== 'string') return [];
  // First try splitting on multiple newlines (true paragraphs)
  let paragraphs = text.split(/\r?\n\s*\r?\n+/).map(p => p.trim()).filter(Boolean);
  // If we got just one long paragraph, try splitting on single newline as fallback
  if (paragraphs.length === 1) {
    paragraphs = text.split(/\r?\n+/).map(p => p.trim()).filter(Boolean);
  }
  return paragraphs;
}

for (let sourceIndex = 0; sourceIndex < items.length; sourceIndex++) {
  const item = items[sourceIndex];
  // common field from ExtractPDF node is `text` — try that, then try other likely keys
  const rawText = item.json?.text ?? item.json?.content ?? item.json?.parsedText ?? "";

  const paragraphs = splitIntoParagraphs(rawText);

  // If no paragraphs found but text exists, treat whole text as single paragraph
  if (paragraphs.length === 0 && rawText) paragraphs.push(rawText.trim());

  // Create chunks by concatenating paragraphs until we exceed maxChars
  const chunks = [];
  let current = "";

  for (let p of paragraphs) {
    // if a single paragraph is longer than maxChars, split it into smaller pieces
    if (p.length > maxChars) {
      // flush current chunk first
      if (current) {
        chunks.push(current.trim());
        current = "";
      }
      // split long paragraph into sub-chunks by sentences or by fixed width fallback
      const sentences = p.match(/[^.!?]+[.!?]*/g) ?? [p];
      let sub = "";
      for (let s of sentences) {
        if ((sub + " " + s).trim().length > maxChars) {
          if (sub) {
            chunks.push(sub.trim());
            sub = s.trim();
          } else {
            // sentence itself bigger than maxChars -> hard split
            for (let i = 0; i < s.length; i += maxChars) {
              chunks.push(s.slice(i, i + maxChars).trim());
            }
            sub = "";
          }
        } else {
          sub = (sub + " " + s).trim();
        }
      }
      if (sub) chunks.push(sub.trim());
      continue;
    }

    if ((current + "\n\n" + p).trim().length <= maxChars && current.length > 0) {
      current = (current + "\n\n" + p).trim();
    } else if (!current) {
      current = p;
    } else {
      // current non-empty and adding p would exceed limit -> push current and start new
      chunks.push(current.trim());
      current = p;
    }
  }

  if (current) chunks.push(current.trim());

  const total = chunks.length;

  // push each chunk as its own n8n item
  for (let i = 0; i < chunks.length; i++) {
    out.push({
      json: {
        chunk_index: i,
        chunk_text: chunks[i],
        total_chunks_for_source: total,
        source_item_index: sourceIndex,
        source_item_id: item.json?.id ?? item.json?.fileName ?? null,
        original_paragraph_count: paragraphs.length,
        // keep original meta if you want:
        // original_meta: item.json
      }
    });
  }
}

// return array of items (one per chunk)
return out;

// Code node (no static storage) - simple filter only
const payloads = $input.all(); // array of incoming items
const out = [];

const WORKFLOW_SIGNATURE = "Automated with this n8n workflow";

for (const p of payloads) {
  const payload = p.json ?? {};
  const event = payload.event ?? payload;

  // ignore bot-origin messages
  if (event.bot_id || event.subtype === 'bot_message') continue;

  // ignore replies from the workflow (by signature)
  const text = event.text || "";
  if (typeof text === 'string' && text.includes(WORKFLOW_SIGNATURE)) continue;

  out.push({ json: payload }); // pass the original payload forward
}

return out;
